syedhaffiz/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/syedhaffiz/subscriptions","type":"User","url":"https://api.github.com/users/syedhaffiz","user_view_type":"public"},"html_url":"https://github.com/syedhaffiz/didactic-octo-happiness/commit/1b6b5e5fee393c1566376ed23f41587cf95806f6","node_id":"C_kwDOSh0tt9oAKDFiNmI1ZTVmZWUzOTNjMTU2NjM3NmVkMjNmNDE1ODdjZjk1ODA2ZjY","parents":[{"html_url":"https://github.com/syedhaffiz/didactic-octo-happiness/commit/e0d0608840e351144110013ae02e8a95969c27c3","sha":"e0d0608840e351144110013ae02e8a95969c27c3","url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/commits/e0d0608840e351144110013ae02e8a95969c27c3"}],"sha":"1b6b5e5fee393c1566376ed23f41587cf95806f6","url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/commits/1b6b5e5fee393c1566376ed23f41587cf95806f6"},{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/25886784?v=4","events_url":"https://api.github.com/users/syedhaffiz/events{/privacy}","followers_url":"https://api.github.com/users/syedhaffiz/followers","following_url":"https://api.github.com/users/syedhaffiz/following{/other_user}","gists_url":"https://api.github.com/users/syedhaffiz/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/syedhaffiz","id":25886784,"login":"syedhaffiz","node_id":"MDQ6VXNlcjI1ODg2Nzg0","organizations_url":"https://api.github.com/users/syedhaffiz/orgs","received_events_url":"https://api.github.com/users/syedhaffiz/received_events","repos_url":"https://api.github.com/users/syedhaffiz/repos","site_admin":false,"starred_url":"https://api.github.com/users/syedhaffiz/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/syedhaffiz/subscriptions","type":"User","url":"https://api.github.com/users/syedhaffiz","user_view_type":"public"},"comments_url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/commits/e0d0608840e351144110013ae02e8a95969c27c3/comments","commit":{"author":{"date"