thDefault` to prevent unintended leakage across unrelated modules.","tree":{"sha":"c2840adefea72761d096a51d4e8abce39513be2a","url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/git/trees/c2840adefea72761d096a51d4e8abce39513be2a"},"url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/git/commits/d2c1b7b3724e4b38f00181522a4097575dd8abab","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/25886784?v=4","events_url":"https://api.github.com/users/syedhaffiz/events{/privacy}","followers_url":"https://api.github.com/users/syedhaffiz/followers","following_url":"https://api.github.com/users/syedhaffiz/following{/other_user}","gists_url":"https://api.github.com/users/syedhaffiz/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/syedhaffiz","id":25886784,"login":"syedhaffiz","node_id":"MDQ6VXNlcjI1ODg2Nzg0","organizations_url":"https://api.github.com/users/syedhaffiz/orgs","received_events_url":"https://api.github.com/users/syedhaffiz/received_events","repos_url":"https://api.github.com/users/syedhaffiz/repos","site_admin":false,"starred_url":"https://api.github.com/users/syedhaffiz/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/syedhaffiz/subscriptions","type":"User","url":"https://api.github.com/users/syedhaffiz","user_view_type":"public"},"html_url":"https://github.com/syedhaffiz/didactic-octo-happiness/commit/d2c1b7b3724e4b38f00181522a4097575dd8abab","node_id":"C_kwDOSh0tt9oAKGQyYzFiN2IzNzI0ZTRiMzhmMDAxODE1MjJhNDA5NzU3NWRkOGFiYWI","parents":[{"html_url":"https://github.com/syedhaffiz/didactic-octo-happiness/commit/945b67cb5eb086ee3a4e99365c556d452cda7c7f","sha":"945b67cb5eb086ee3a4e99365c556d452cda7c7f","url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/commits/945b67cb5eb086ee3a4e99365c556d452cda7c7f"}],"sha":"d2c1b7b3724e4b38f00181522a4097575dd8abab","url"