ue route and wire the new routes throughout the codebase.","tree":{"sha":"66b82620fe1d45508bd6e3f4082c5d03bff882a3","url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/git/trees/66b82620fe1d45508bd6e3f4082c5d03bff882a3"},"url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/git/commits/4706455b6a6c5c2201477fea349b9d6d6615e475","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/25886784?v=4","events_url":"https://api.github.com/users/syedhaffiz/events{/privacy}","followers_url":"https://api.github.com/users/syedhaffiz/followers","following_url":"https://api.github.com/users/syedhaffiz/following{/other_user}","gists_url":"https://api.github.com/users/syedhaffiz/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/syedhaffiz","id":25886784,"login":"syedhaffiz","node_id":"MDQ6VXNlcjI1ODg2Nzg0","organizations_url":"https://api.github.com/users/syedhaffiz/orgs","received_events_url":"https://api.github.com/users/syedhaffiz/received_events","repos_url":"https://api.github.com/users/syedhaffiz/repos","site_admin":false,"starred_url":"https://api.github.com/users/syedhaffiz/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/syedhaffiz/subscriptions","type":"User","url":"https://api.github.com/users/syedhaffiz","user_view_type":"public"},"html_url":"https://github.com/syedhaffiz/didactic-octo-happiness/commit/4706455b6a6c5c2201477fea349b9d6d6615e475","node_id":"C_kwDOSh0tt9oAKDQ3MDY0NTViNmE2YzVjMjIwMTQ3N2ZlYTM0OWI5ZDZkNjYxNWU0NzU","parents":[{"html_url":"https://github.com/syedhaffiz/didactic-octo-happiness/commit/e42ed560f6c63abacc99d50d8f43bb001da3b3a6","sha":"e42ed560f6c63abacc99d50d8f43bb001da3b3a6","url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/commits/e42ed560f6c63abacc99d50d8f43bb001da3b3a6"}],"sha":"4706455b6a6c5c2201477fea349b9d6d6615e475","url":"https:/