illed with a real range on first load and simplifies range handling/formatting.","tree":{"sha":"f3f0c1d7661e8c0fa18980393c31df1d988ab29f","url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/git/trees/f3f0c1d7661e8c0fa18980393c31df1d988ab29f"},"url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/git/commits/192cfe2d1720325c501c97d0ab467ae2a67d9417","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/25886784?v=4","events_url":"https://api.github.com/users/syedhaffiz/events{/privacy}","followers_url":"https://api.github.com/users/syedhaffiz/followers","following_url":"https://api.github.com/users/syedhaffiz/following{/other_user}","gists_url":"https://api.github.com/users/syedhaffiz/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/syedhaffiz","id":25886784,"login":"syedhaffiz","node_id":"MDQ6VXNlcjI1ODg2Nzg0","organizations_url":"https://api.github.com/users/syedhaffiz/orgs","received_events_url":"https://api.github.com/users/syedhaffiz/received_events","repos_url":"https://api.github.com/users/syedhaffiz/repos","site_admin":false,"starred_url":"https://api.github.com/users/syedhaffiz/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/syedhaffiz/subscriptions","type":"User","url":"https://api.github.com/users/syedhaffiz","user_view_type":"public"},"html_url":"https://github.com/syedhaffiz/didactic-octo-happiness/commit/192cfe2d1720325c501c97d0ab467ae2a67d9417","node_id":"C_kwDOSh0tt9oAKDE5MmNmZTJkMTcyMDMyNWM1MDFjOTdkMGFiNDY3YWUyYTY3ZDk0MTc","parents":[{"html_url":"https://github.com/syedhaffiz/didactic-octo-happiness/commit/8ee05979481909d58958ea5fefccc2b95ecabeaf","sha":"8ee05979481909d58958ea5fefccc2b95ecabeaf","url":"https://api.github.com/repos/syedhaffiz/didactic-octo-happiness/commits/8ee05979481909d58958ea5fefccc2b95ecabeaf"}],"sha":"192cfe2d1720325c501c97d0ab467ae2a6