 chip in CallersPage","tree":{"sha":"bd4ce2a852d8b39d2b37b71feacaf5fafb3f2f1d","url":"https://api.github.com/repos/bright-guard/bright-guard/git/trees/bd4ce2a852d8b39d2b37b71feacaf5fafb3f2f1d"},"url":"https://api.github.com/repos/bright-guard/bright-guard/git/commits/3f620638e73563c1d19f556df20386eb6c58a069","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/366029?v=4","events_url":"https://api.github.com/users/daniel-garcia/events{/privacy}","followers_url":"https://api.github.com/users/daniel-garcia/followers","following_url":"https://api.github.com/users/daniel-garcia/following{/other_user}","gists_url":"https://api.github.com/users/daniel-garcia/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/daniel-garcia","id":366029,"login":"daniel-garcia","node_id":"MDQ6VXNlcjM2NjAyOQ==","organizations_url":"https://api.github.com/users/daniel-garcia/orgs","received_events_url":"https://api.github.com/users/daniel-garcia/received_events","repos_url":"https://api.github.com/users/daniel-garcia/repos","site_admin":false,"starred_url":"https://api.github.com/users/daniel-garcia/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/daniel-garcia/subscriptions","type":"User","url":"https://api.github.com/users/daniel-garcia","user_view_type":"public"},"html_url":"https://github.com/bright-guard/bright-guard/commit/3f620638e73563c1d19f556df20386eb6c58a069","node_id":"C_kwDOSib9GNoAKDNmNjIwNjM4ZTczNTYzYzFkMTlmNTU2ZGYyMDM4NmViNmM1OGEwNjk","parents":[{"html_url":"https://github.com/bright-guard/bright-guard/commit/42c8bf592b2a6abb8c8fdbd835f1e23abeb1374e","sha":"42c8bf592b2a6abb8c8fdbd835f1e23abeb1374e","url":"https://api.github.com/repos/bright-guard/bright-guard/commits/42c8bf592b2a6abb8c8fdbd835f1e23abeb1374e"}],"sha":"3f620638e73563c1d19f556df20386eb6c58a069","url":"https://api.github.com/repos/bright-guard/bright-guard/co